from AlgorithmImports import *

class MultiStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.tickers = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.sma = self.SMA(self.spy, 20, Resolution.Daily)
        self.rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.spy_prev_close = None
        self.spy_prev_sma = None

        self.aapl_close_history = []

        self.lotA_shares = 0
        self.lotB_shares = 0

        self.SetWarmUp(50)

    def OnData(self, data: Slice):
        for t in self.tickers:
            if not data.ContainsKey(t) or data[t] is None:
                return

        if not self.sma.IsReady or not self.rsi.IsReady:
            self._update_history(data)
            return

        spy_close = data[self.spy].Close
        aapl_close = data[self.aapl].Close

        sma_value = self.sma.Current.Value
        rsi_value = self.rsi.Current.Value

        # Slot 1 - Strategy A (SPY)
        if self.spy_prev_close is not None and self.spy_prev_sma is not None:
            if self.lotA_shares > 0:
                # sell reason: crosses below SMA
                if self.spy_prev_close <= self.spy_prev_sma and spy_close < sma_value:
                    pass
                crossed_below = (self.spy_prev_close >= self.spy_prev_sma) and (spy_close < sma_value)
                if crossed_below:
                    self.Sell(self.spy, self.lotA_shares)
                    self.lotA_shares = 0
            else:
                crossed_above = (self.spy_prev_close <= self.spy_prev_sma) and (spy_close > sma_value)
                if crossed_above:
                    portfolio_value = self.Portfolio.TotalPortfolioValue
                    invest_amount = 0.40 * portfolio_value
                    shares = int(invest_amount // spy_close)
                    if shares > 0:
                        self.Buy(self.spy, shares)
                        self.lotA_shares += shares

        # Slot 2 - Strategy B (AAPL)
        if self.lotB_shares > 0:
            if rsi_value > 60:
                self.Sell(self.aapl, self.lotB_shares)
                self.lotB_shares = 0
        else:
            if self._is_red_streak(3):
                cash = self.Portfolio.Cash
                cost = 20000.0
                if cash >= cost:
                    shares = int(cost // aapl_close)
                    if shares > 0:
                        self.Buy(self.aapl, shares)
                        self.lotB_shares += shares

        self._update_history(data)

        self.spy_prev_close = spy_close
        self.spy_prev_sma = sma_value

    def _update_history(self, data: Slice):
        aapl_close = data[self.aapl].Close
        self.aapl_close_history.append(aapl_close)
        if len(self.aapl_close_history) > 10:
            self.aapl_close_history.pop(0)

    def _is_red_streak(self, n):
        if len(self.aapl_close_history) < n + 1:
            return False
        recent = self.aapl_close_history[-(n + 1):]
        for i in range(1, len(recent)):
            if not (recent[i] < recent[i - 1]):
                return False
        return True

