class DualStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            equity = self.AddEquity(ticker, Resolution.Daily)
            self.symbols[ticker] = equity.Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.sma = self.SMA(self.spy, 20, Resolution.Daily)
        self.rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.spy_prev_close = None
        self.spy_prev_sma = None

        self.aapl_close_history = []

        self.lotA_shares = 0
        self.lotB_shares = 0

    def OnData(self, data: Slice):
        for ticker, symbol in self.symbols.items():
            if not data.Bars.ContainsKey(symbol):
                return

        spy_bar = data.Bars[self.spy]
        aapl_bar = data.Bars[self.aapl]

        spy_close = spy_bar.Close
        aapl_close = aapl_bar.Close

        self.aapl_close_history.append(aapl_close)
        if len(self.aapl_close_history) > 10:
            self.aapl_close_history.pop(0)

        sma_ready = self.sma.IsReady
        rsi_ready = self.rsi.IsReady

        sma_value = self.sma.Current.Value if sma_ready else None

        cross_above = False
        cross_below = False
        if sma_ready and self.spy_prev_close is not None and self.spy_prev_sma is not None:
            if self.spy_prev_close <= self.spy_prev_sma and spy_close > sma_value:
                cross_above = True
            if self.spy_prev_close >= self.spy_prev_sma and spy_close < sma_value:
                cross_below = True

        # Strategy A - sell before buy
        if self.lotA_shares > 0:
            if cross_below:
                self.MarketOrder(self.spy, -self.lotA_shares)
                self.lotA_shares = 0
        else:
            if sma_ready and cross_above:
                target_value = 0.40 * self.Portfolio.TotalPortfolioValue
                shares = int(math.floor(target_value / spy_close))
                if shares > 0:
                    self.MarketOrder(self.spy, shares)
                    self.lotA_shares += shares

        # Strategy B - red streak of 3
        red3 = False
        if len(self.aapl_close_history) >= 4:
            h = self.aapl_close_history
            c0, c1, c2, c3 = h[-4], h[-3], h[-2], h[-1]
            if c1 < c0 and c2 < c1 and c3 < c2:
                red3 = True

        if self.lotB_shares > 0:
            if rsi_ready and self.rsi.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.lotB_shares)
                self.lotB_shares = 0
        else:
            if red3:
                cash_needed = 20000.0
                if self.Portfolio.Cash >= cash_needed:
                    shares = int(math.floor(cash_needed / aapl_close))
                    if shares > 0:
                        self.MarketOrder(self.aapl, shares)
                        self.lotB_shares += shares

        self.spy_prev_close = spy_close
        self.spy_prev_sma = sma_value if sma_ready else self.spy_prev_sma

