        rsi_val = self.rsi.Current.Value

        # ---- Strategy A: sell before buy ----
        if self.a_shares > 0:
            if self.a_prev_close is not None and self.a_prev_sma is not None:
                if self.a_prev_close <= self.a_prev_sma and spy_close < sma_val:
                    pass
            # sell condition: crosses below SMA
            if self.a_prev_close is not None and self.a_prev_sma is not None:
                if self.a_prev_close <= self.a_prev_sma and spy_close < sma_val:
                    self.MarketOrder(self.spy, -self.a_shares)
                    self.a_shares = 0
        else:
            if self.a_prev_close is not None and self.a_prev_sma is not None:
                if self.a_prev_close <= self.a_prev_sma and spy_close > sma_val:
                    invest_amount = 0.40 * self.Portfolio.TotalPortfolioValue
                    qty = int(invest_amount // spy_close)
                    if qty > 0:
                        self.MarketOrder(self.spy, qty)
                        self.a_shares = qty

        # ---- Strategy B: sell before buy ----
        self._update_history(aapl_close)

        if self.b_shares > 0:
            if rsi_val > 60:
                self.MarketOrder(self.aapl, -self.b_shares)
                self.b_shares = 0
        else:
            if self._is_red_streak(3):
                cost = 20000.0
                if self.Portfolio.Cash >= cost:
                    qty = int(cost // aapl_close)
                    if qty > 0:
                        self.MarketOrder(self.aapl, qty)
                        self.b_shares = qty

        self.a_prev_close = spy_close
        self.a_prev_sma = sma_val

    def _update_history(self, close):
        self.aapl_closes.append(close)
        if len(self.aapl_closes) > 10:
            self.aapl_closes.pop(0)

    def _is_red_streak(self, n):
        if len(self.aapl_closes) < n + 1:
            return False
        recent = self.aapl_closes[-(n + 1):]
        for i in range(1, len(recent)):
            if not (recent[i] < recent[i - 1]):
