from AlgorithmImports import *

class MultiStrategyAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for t in self.tickers:
            equity = self.AddEquity(t, Resolution.Daily)
            equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
            self.symbols[t] = equity.Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.sma_period = 20
        self.sma = self.SMA(self.spy, self.sma_period, Resolution.Daily)
        self.rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        # Strategy A state
        self.a_lot_shares = 0
        self.a_prev_close = None
        self.a_prev_sma = None

        # Strategy B state
        self.b_lot_shares = 0
        self.b_prev_close_hist = []  # to track consecutive red days
        self.b_prev_aapl_close = None
        self.b_red_streak = 0
        self.b_prev_rsi = None

        self.warmup_bars_needed = max(self.sma_period, 14) + 5
        self.SetWarmUp(self.warmup_bars_needed, Resolution.Daily)

    def OnData(self, data: Slice):
        # Skip if any subscribed ticker missing today's bar
        for t in self.tickers:
            sym = self.symbols[t]
            if not data.ContainsKey(sym) or data[sym] is None:
                return
            if not data.Bars.ContainsKey(sym):
                return

        if self.IsWarmingUp:
            return

        if not self.sma.IsReady or not self.rsi.IsReady:
            return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        # --- Update AAPL red-day streak using previous close ---
        if self.b_prev_aapl_close is not None:
            if aapl_close < self.b_prev_aapl_close:
                self.b_red_streak += 1
            else:
                self.b_red_streak = 0

        # --- Strategy A: SMA cross ---
        sma_value = self.sma.Current.Value

        a_cross_above = False
        a_cross_below = False
        if self.a_prev_close is not None and self.a_prev_sma is not None:
            if self.a_prev_close <= self.a_prev_sma and spy_close > sma_value:
                a_cross_above = True
            if self.a_prev_close >= self.a_prev_sma and spy_close < sma_value:
                a_cross_below = True

        # Sell before buy
        if self.a_lot_shares > 0:
            if a_cross_below:
