        self.a_shares = 0
        self.a_prev_close = None
        self.a_prev_sma = None

        # Strategy B state (AAPL)
        self.b_shares = 0
        self.aapl_close_history = []  # store recent closes for red-day streak
        self.b_prev_close = None

        self.prev_closes = {t: None for t in tickers}

        self.SetWarmUp(60)

    def OnData(self, data: Slice):

        tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        for t in tickers:
            sym = self.symbols[t]
            if not data.ContainsKey(sym) or data[sym] is None:
                return

        if self.IsWarmingUp:
            for t in tickers:
                sym = self.symbols[t]
                self.prev_closes[t] = data[sym].Close
            return

        if not (self.sma.IsReady and self.rsi.IsReady):
            for t in tickers:
                sym = self.symbols[t]
                self.prev_closes[t] = data[sym].Close
            return

        spy_close = data[self.spy].Close
        aapl_close = data[self.aapl].Close

        sma_val = self.sma.Current.Value
        rsi_val = self.rsi.Current.Value

        prev_spy_close = self.prev_closes["SPY"]
        prev_aapl_close = self.prev_closes["AAPL"]

        # We need previous SMA value to evaluate cross; approximate using prior bar's SMA
        # Track previous sma using a simple buffer
        if self.a_prev_sma is None:
            prev_sma_val = sma_val
        else:
            prev_sma_val = self.a_prev_sma

        # ----- Strategy A: SELL then BUY -----
        if self.a_shares > 0:
            # sell reason: close crosses below sma
            crosses_below = (prev_spy_close is not None) and (prev_spy_close >= prev_sma_val) and (spy_close < sma_val)
            if crosses_below:
                self.MarketOrder(self.spy, -self.a_shares)
                self.a_shares = 0
        else:
            crosses_above = (prev_spy_close is not None) and (prev_spy_close <= prev_sma_val) and (spy_close > sma_val)
            if crosses_above:
                target_value = 0.40 * self.Portfolio.TotalPortfolioValue
                qty = int(target_value // spy_close)
                if qty > 0:
                    self.MarketOrder(self.spy, qty)
                    self.a_shares += qty

        # ----- Strategy B: SELL then BUY -----
        # update aapl close history for red-day streak calculation
        self.aapl_close_history.append(aapl_close)
        if len(self.aapl_close_history) > 10:
            self.aapl_close_history.pop(0)

        if self.b_shares > 0:
            if rsi_val > 60:
                self.MarketOrder(self.aapl, -self.b_shares)
                self.b_shares = 0
        else:
            # check red for 3 consecutive days (today completes it)
            red_streak = self._consecutive_red_days()
            if red_streak >= 3:
                cash = self.Portfolio.Cash
                if cash >= 20000:
                    qty = int(20000 // aapl_close)
                    if qty > 0:
                        self.MarketOrder(self.aapl, qty)
                        self.b_shares += qty

        # update prev state
        for t in tickers:
            sym = self.symbols[t]
            self.prev_closes[t] = data[sym].Close
        self.a_prev_sma = sma_val

    def _consecutive_red_days(self):
        # aapl_close_history holds recent closes including today, most recent last
        hist = self.aapl_close_history
        streak = 0
        for i in range(len(hist) - 1, 0, -1):
            if hist[i] < hist[i - 1]:
                streak += 1
            else:
                break
        return streak

